int16_t sin_fast_q14_8192(uint16_t angle)
{
    // wrap
    angle &= ANGLE_MASK;
    // 象限
    uint16_t quadrant = angle >> 11;   // /2048
    // 索引
    uint16_t idx = angle & (QUADRANT - 1);
    // 镜像（减少表）
    if (quadrant & 1) {
        idx = QUADRANT - idx;
    }
    int16_t value = sin_table[idx];
    // 符号
    if (quadrant >= 2) {
        value = -value;
    }

    return value;
}

int16_t value_x_sindeg(int16_t value, uint16_t angle_x10)
{
    uint16_t angle = angle_map_deg2bit(angle_x10);
    int16_t sin_value = sin_fast_q14_8192(angle);
    return (int16_t)(((int32_t)value * sin_value) >> 14);
}
